import type { SaintRec } from "./types";

export const M12: SaintRec[] = [
  { key: "12-01", name: "Мч. Платона Анкирского", kind: "saint", desc: "Святой мученик Платон, брат святого мученика Антиоха врача (память 29 июля), родился в городе Анкире в Галатии в благочестивой семье. Еще юношей он оставил дом и ходил по городам, вдохновенно проповедуя Слово Божие язычникам, удивляя слушат" },
  { key: "12-01", name: "Собор святых Эстонской земли", kind: "feast", desc: "Собор был установлен указом патриарха Московского и всея Руси Алексия II от 22 июля 2002 года по ходатайству руководства Эстонской Православной Церкви Московского Патриархата." },
  { key: "12-01", name: "Св. Николая Виноградова, исп., пресвитера", kind: "saint", desc: "25 июля 1908 года, за полгода до своей кончины, святой праведный Иоанн Кронштадтский записывает в своем дневнике карандашом: &quot;Священник Николай Васильевич Виноградов, Ярославской губернии Романовского уезда, село Малахово&quot;." },
  { key: "12-02", name: "Прор. Авдия (из 12-ти)", kind: "saint", desc: "Святой пророк Авдий был родом из села Вифарама, близ Сихема [1] ; он служил при дворе царей Израильских и был домоправителем у царя Ахава [2] . От юности своей он был весьма богобоязнен, и когда весь Израиль отступил от Бога и стал поклонят" },
  { key: "12-02", name: "мч. Варлаама", kind: "saint", desc: "Святой мученик Варлаам жил в Антиохии Сирийской. Во время гонения на христиан императора Диоклитиана (284–305) святой Варлаам в престарелом возрасте был схвачен, приведен на суд, где исповедал себя христианином." },
  { key: "12-02", name: "свт. Филарета, митрополита Московского (Дроздова)", kind: "saint", desc: "Свт. Филарет (Дроздов, 1782–1867) ‒ один из наиболее влиятельных иерархов Русской Православной Церкви XIX века. Выпускник Троице-Сергиевой Лавры, он стал выдающимся проповедником, богословом и ректором Санкт-Петербургской духовной академии." },
  { key: "12-02", name: "Прп. Варлаама, игумена Печерского, в Ближних пещерах", kind: "saint", desc: "Первый игумен Киево-Печерского монастыря. С молодых лет часто посещая преподобного Антония Печерского (&dagger; 1073 г.; память 10/23 июля) и с любовью слушая его наставления, он так увлекся монашеской жизнью, что решил сам стать иноком." },
  { key: "12-02", name: "Обретение мощей прмч. Адриана Пошехонского, Ярославского, игумена", kind: "saint", desc: "Был учеником преподобного Корнилия Комельского, вначале подвизался в Вологодском Комельском монастыре и был искусным иконописцем. По благословению игумена 13 сентября 1540 г., взяв икону Успения Пресвятой Богородицы , преподобный Адриан вме" },
  { key: "12-02", name: "мч. Азы и с ним 150-ти воинов", kind: "saint", desc: "Святой мученик Аза был воином в Исаврии [1] при царе Диоклитиане. Но потом, желая быть воином не земного царя, а Небесного, он оставил воинское звание и удалился в пустыню." },
  { key: "12-02", name: "мч. Илиодора Магидского (Памфилийского) (ок. 273).", kind: "saint", desc: "В царствование Аврелиана [1] в памфилийском [2] городе Магидисе, которым управлял Аеций, безбоязненно проповедовал Христа один благочестивый человек, именем Илиодор." },
  { key: "12-02", name: "прп. Илариона Грузина, чудотворца, иеромонаха (ок. 875)", kind: "saint", desc: "Преподобный Иларион чудотворец родился в 816 г. в Кахетии (Восточная Грузия). Он происходил из рода грузинских князей Вачнадзе (Донаури). В мальчике очень рано проявилась склонность к подвижничеству." },
  { key: "12-02", name: "прп. Порфирия Кавсокаливита (Баирактариса)", kind: "saint", desc: "Старец Порфирий, в миру Евангелос Баирактарис, родился 7 февраля 1906 года в Греции, в селении Айос-Иоаннис близ города Карист на острове Эвбея. Его родители были бедные благочестивые крестьяне." },
  { key: "12-02", name: "Собор новомучеников и исповедников Крымской митрополии", kind: "feast", desc: "Поименный список Собора новомучеников и исповедников Крымской митрополии утвержден решением Священного Синода 12 марта 2024 года (журнал № 20). Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметил" },
  { key: "12-02", name: "Сщмч. Иоанна Вишневского, пресвитера", kind: "saint", desc: "Иван Всеволодович Вишневский родился 6 октября 1888 года в семье священника села Федьковка Шуралинской волости Екатеринбургской губернии. Он окончил духовное училище и один класс духовной семинарии." },
  { key: "12-02", name: "Порфирия (Гулевича), епископа Симферопольского", kind: "saint", desc: "Епископ Симферопольский и Крымский Порфирий (в миру Поликарп Васильевич Гулевич) родился 26 февраля 1864 года в селе Токаревка Литинского уезда Подольской губернии в семье священника." },
  { key: "12-02", name: "Иоасафа (Удалова), епископа Чистопольского", kind: "saint", desc: "Иоасаф (в миру Иван Иванович Удалов) (5 апреля 1886, Уфа – 2 декабря 1937, Казань) – епископ Чистопольский, викарий Казанской епархии. Причислен к лику святых Русской Православной Церкви в 2008 году." },
  { key: "12-02", name: "Сергия Махаева", kind: "saint", desc: "Священномученик Сергий родился 6 сентября 1874 года в семье священника Константина Георгиевича Махаева, служившего в Спасской церкви села Усово Московского уезда, где находилось имение великого князя Сергея Александровича." },
  { key: "12-03", name: "Предпразднство Введения во Храм Пресвятой Богородицы", kind: "feast", desc: "Праздник Введения во храм Богородицы — самый поздний среди двунадесятых. До VIII века воспоминание введения Девы Марии во храм было содержанием праздника Рождества Богородицы, о чем говорит 2-й канон Рождества Богородицы, составленный препо" },
  { key: "12-03", name: "Прп. Григория Декаполита", kind: "saint", desc: "Родился в г. Иринополе в Десятиградии (по-гречески Декаполь) в благочестивой христианской семье. Еще в юности он хорошо изучил Слово Божие и вверил ум свой к Богу." },
  { key: "12-03", name: "свт. Прокла, архиепископа Константинопольского", kind: "saint", desc: "Святитель Прокл, архиепископ Константинопольский, с юных лет все свое время отдавал молитве и изучению Священного Писания. Господь удостоил его великого счастья быть учеником святителя Иоанна Златоуста (&dagger; 407, память 13 ноября), который рукоположил его сначала в сан диакона, а затем в сан пресвитера." },
  { key: "12-03", name: "Прп. Диодора Юрьегорского", kind: "saint", desc: "Преподобный Диодор Юрьегорский (Дамиан) родился в селе Турчасово на реке Онеге. Родители его – Иерофей и Мария – назвали сына Диомидом. Пятнадцатилетним юношей он отправился на богомолье в Соловецкий монастырь и остался там послушником." },
  { key: "12-03", name: "мч. Дасия Доростольского", kind: "saint", desc: "Святой мученик Дасий жил в III веке в городе Доростоле на Дунае. Жители города готовились к празднику в честь языческого бога Сатурна. По обычаю за 30 дней до праздника язычники выбирали прекрасного юношу, одевали его в роскошные одежды, оказывали ему царские почести, а в день праздника приносили в жертву богу." },
  { key: "12-03", name: "Алексия Аманова", kind: "saint", desc: "Священномученик Алексий родился 9 февраля 1870 года в городе Касимове Рязанской губернии в семье псаломщика Иоанна Аманова, три сына которого впоследствии стали священниками." },
  { key: "12-03", name: "Александра Сахарова", kind: "saint", desc: "Священномученик Александр родился 15 августа 1875 года в селе Кривандино Егорьевского уезда Рязанской губернии в семье диакона Нестора Сахарова. В 1890 году после окончания Зарайского Духовного училища Александр поступил в Рязанскую Духовную семинарию." },
  { key: "12-03", name: "Владимира Медведюка", kind: "saint", desc: "Священномученик Владимир родился 15 июля 1888 года на территории современной Польши в городе Луков Седлецкой губернии в благочестивой семье железнодорожного рабочего Фаддея Медведюка." },
  { key: "12-03", name: "Алексия Никатова", kind: "saint", desc: "Священномученик Алексий родился в 1875 году в Польше, в селе Дофнары Брест-Литовского уезда Гродненской губернии в семье сельского учителя Гавриила Никатова." },
  { key: "12-03", name: "Василия Канделяброва", kind: "saint", desc: "Священномученик протоиерей Иоанн Романович Сарв родился в 1867 году в Лифляндской губернии в семье безземельного крестьянина. Окончил Рижскую Духовную Семинарию, получил должность псаломщика и вскоре был рукоположен во иерея к храму в селе Ольгин Крест в Гдовском уезде Санкт-Петербургской губернии." },
  { key: "12-03", name: "Николая Зеленова", kind: "saint", desc: "Священномученик Николай родился в 1887 году в сельце Бочевино Бронницкого уезда Московской губернии в семье крестьянина Поликарпа Зеленова. С 1897 года он был певчим церковного хора." },
  { key: "12-03", name: "Иоанна Заболотного, иеромонаха", kind: "saint", desc: "Преподобномученик Иоанн (в миру Иван Васильевич Заболотный) родился в 1899 году в селе Клиновое Балтского уезда Подольской губернии (ныне Голованевского района Кировоградской области, Украина) в крестьянской семье." },
  { key: "12-03", name: "Арсения (Дмитриева), игумена", kind: "saint", desc: "Священномученик протоиерей Иоанн Романович Сарв родился в 1867 году в Лифляндской губернии в семье безземельного крестьянина. Окончил Рижскую Духовную Семинарию, получил должность псаломщика и вскоре был рукоположен во иерея к храму в селе Ольгин Крест в Гдовском уезде Санкт-Петербургской губернии." },
  { key: "12-03", name: "Евтихия (Качура), игумена", kind: "saint", desc: "Преподобномученик Евтихий (в миру Евфимий Викторович Качур) родился 26 декабря 1891 года в слободе Алексеевка Бирюченского уезда Воронежской губернии в день памяти священномученика Евфимия, епископа Сардийского, который долгие годы в изгнании противостоял ереси иконоборчества." },
  { key: "12-04", name: "Введение (Вход) во Храм Пресвятой Владычицы нашей Богородицы и Приснодевы Марии", kind: "feast", desc: "Праздник Введения во храм Богородицы — самый поздний среди двунадесятых. До VIII века воспоминание введения Девы Марии во храм было содержанием праздника Рождества Богородицы, о чем говорит 2-й канон Рождества Богородицы, составленный препо" },
  { key: "12-05", name: "Попразднство Введения", kind: "feast", desc: "Праздник Введения во храм Богородицы — самый поздний среди двунадесятых. До VIII века воспоминание введения Девы Марии во храм было содержанием праздника Рождества Богородицы, о чем говорит 2-й канон Рождества Богородицы, составленный препо" },
  { key: "12-05", name: "блгв. кн. Михаила Ярославича Тверского", kind: "saint", desc: "Михаил, святой великий князь Тверской, сын Ярослава III , внук Ярослава II Всеволодовича , родился в 1272 году, вскоре по смерти отца, от второй супруги его Ксении; прозван Тверским, ибо княжил в Твери, не быв еще великим князем, и первый утвердил независимость Тверского княжения." },
  { key: "12-05", name: "Блгв. кн. Ярополка, во Святом Крещении Петра, Владимиро-Волынского", kind: "saint", desc: "Имя Петр дано ему было при Крещении. Сын Киевского князя Изяслава, внук Ярослава Мудрого и правнук св. равноапостольного Владимира. Точное время рождения св." },
  { key: "12-05", name: "мч. Прокопия Кесарийского, чтеца", kind: "saint", desc: "Святой мученик Прокопий был чтецом в Иерусалимской церкви. Он вел строгую подвижническую жизнь, за что стяжал от Господа дар изгонять бесов. Ревностный проповедник Слова Божия был схвачен и приведен на суд в Кесарию Палестинскую." },
  { key: "12-05", name: "мч. Менигна", kind: "saint", desc: "Святой мученик Менигн был простым ремесленником, занимался отбеливанием холстов. Господь даровал ему Свою особую милость. Дважды в своей жизни он слышал глас с Неба, призывавший его пострадать за Христа." },
  { key: "12-05", name: "прп. Агаввы Исмаильтянина", kind: "saint", desc: "Преподобный Агавва был родом измаильтянин. Оставив свое отечество, родителей и богатства, он последовал за одним иноком, от которого принял монашеский образ." },
  { key: "12-05", name: "прав. Михаила воина, болгарина", kind: "saint", desc: "Святой Михаил воин, из числа первых христиан Болгарии, жил в городе Потуке во время правления императора Михаила III Пьяного (855–867). Происходил из старинного болгарского рода." },
  { key: "12-05", name: "Сщмч. Владимира Рясенского, пресвитера", kind: "saint", desc: "Священномученик Владимир родился в 1891 году в городе Осташкове Тверской губернии в семье священника Федора Рясенского. По окончании Тверской Духовной семинарии он был рукоположен в сан священника к церкви села Спас-Есеновичи Вышневолоцкого уезда." },
  { key: "12-05", name: "Иоасафа (Жевахова), епископа Могилевского", kind: "saint", desc: "Священномученик Иоасаф, епископ Могилевский (в миру Владимир Давидович Жевахов), родился в 1874 году в Полтавской губернии, он происходил из княжеского рода и был потомком святителя Иоасафа Белгородского." },
  { key: "12-05", name: "Иоанна Баранова", kind: "saint", desc: "Иван Самсонович Баранов родился в 1874 году на территории современной Белоруссии, в селе Рудня-Прибытковская Гомельской губернии. С 1895 по 1911 год он служил учителем, а в 1911 году был рукоположен в сан иерея." },
  { key: "12-05", name: "Василия Бовы", kind: "saint", desc: "Василий Иосифович Бова родился в 1877 году в городе Кургане Тобольской губернии. Окончил Духовное училище, в 1909–1914 гг. служил псаломщиком в храме в селе Новоуральском Акмолинской области." },
  { key: "12-05", name: "Павла Евдокимова", kind: "saint", desc: "Павел Васильевич Евдокимов родился в селе Очаково Зубополянского района Тамбовской области 17 августа 1877 года. Об этом священномученике известно мало, служил он в одной из церквей города Вышний Волочек, в этом городе его и арестовали 25 ноября 1937 года." },
  { key: "12-05", name: "Иакова Соколова", kind: "saint", desc: "Священномученик Иаков родился в 1874 году в селе Тимоново Дмитровского уезда Московской губернии в семье псаломщика Ивана Соколова. Окончил двухклассное училище и в 1893 году был назначен служить псаломщиком в Введенскую церковь погоста Черная Грязь." },
  { key: "12-05", name: "Феодора Гусева", kind: "saint", desc: "Священномученик Феодор родился 2 февраля 1875 года в семье священника села Никольское Клинского уезда Московской губернии Евдокима Гусева. Окончил Дмитровское Духовное училище." },
  { key: "12-06", name: "Попразднство Введения", kind: "feast", desc: "Праздник Введения во храм Богородицы — самый поздний среди двунадесятых. До VIII века воспоминание введения Девы Марии во храм было содержанием праздника Рождества Богородицы, о чем говорит 2-й канон Рождества Богородицы, составленный препо" },
  { key: "12-06", name: "Свт. Амфилохия, епископа Иконийского", kind: "icon", desc: "Святитель Амфилохий, епископ Иконийский, родился в Кесарии Каппадокийской, в городе, давшем миру величайших отцов и учителей Православной Церкви. Двоюродный брат святого Григория Богослова , близкий друг святого Василия Великого , их ученик" },
  { key: "12-06", name: "свт. Григория, епископа Акрагантийского", kind: "saint", desc: "Святитель Григорий, епископ Акрагантийский, родился на острове Сицилия, в селении Претория, недалеко от города Акраганта, от благочестивых Харитона и Феодотии." },
  { key: "12-06", name: "блгв. вел. кн. Александра Невского, в схиме Алексия", kind: "saint", desc: "11 июля (переходящая) - Соборы Новгородских, Санкт-Петербургских, Псковских и Волгоградских святых Св. блгв. кн. Александр Невский (1221–1263) ‒ новгородский князь, великий полководец и дипломат." },
  { key: "12-06", name: "свт. Митрофана, в схиме Макария, епископа Воронежского", kind: "saint", desc: "Свт. Митрофан Воронежский (1623-1703) – выдающийся архипастырь XVII века. Родился во Владимирской земле, 40 лет прожил в миру, овдовев, принял монашество." },
  { key: "12-06", name: "Сисиния, епископа Кизического (III),", kind: "saint", desc: "Святый мученик Сисиний происходил из города Кизика [1] . Он претерпел мучения в царствование Диоклитиана от правителя города Александра. За исповедание Христа он был привязан к диким коням, был бит без милосердия, причем в ноздри ему лили крепкий уксус." },
  { key: "12-06", name: "Феодора Антиохийского", kind: "saint", desc: "Святой мученик Феодор Антиохийский, пятнадцатилетний отрок, за исповедание Христа был предан жестоким пыткам императором Юлианом Отступником (361–363)." },
  { key: "12-06", name: "прп. Колумбана, игумена Люксейского", kind: "saint", desc: "Преподобный Колумбан (543–615), игумен Люксейский и Боббийский. Был рожден в Лейнстере (Ирландия). Получил образование в Бангоре в графстве Даун. Около 590 года св." },
  { key: "12-06", name: "Сщмч. Филиппа Распопова", kind: "saint", desc: "Филипп Кузьмич Распопов родился в селе Матвеевка Бугурусланского уезда, Самарской губернии 3 октября 1875 года, крестьянский сын. После окончания церковно-приходской школы Филипп Распопов пребывал послушником в Никольском монастыре города С" },
  { key: "12-06", name: "прмч. Серафима (Тьевара), монаха", kind: "saint", desc: "Преподобномученик Серафим (в миру Антоний Максимович Тьевар) родился 30 июля 1899 года в Москве. Отец умер, когда Антонию исполнилось шесть лет, а его брату Максиму один год, и детей воспитывала мать, Наталия Дмитриевна." },
  { key: "12-06", name: "св. Иоанна Васильева, исп.", kind: "saint", desc: "Исповедник Иоанн родился в 1869 году в селе Мартьяново Серпуховского уезда Московской губернии в семье рабочего-слесаря Сергея Васильева. С 1884 года он работал в харчевной лавке фабрики Рябова, где стал со временем приказчиком." },
  { key: "12-06", name: "сщмч. Елеазара Спиридонова, пресвитера", kind: "saint", desc: "Священномученик священник Елеазар Спиридонов родился в 1874 году в Крыму, в Евпатории, в семье крымских греков. Отец его работал приказчиком на соляных промыслах." },
  { key: "12-06", name: "мч. Александра Уксусова", kind: "saint", desc: "Мученик Александр (Александр Александрович Уксусов) родился в 1874 г. в благочестивой крестьянской семье. Закончив школу, он, как и его родители, работал на земле." },
  { key: "12-07", name: "Попразднство Введения", kind: "feast", desc: "Праздник Введения во храм Богородицы — самый поздний среди двунадесятых. До VIII века воспоминание введения Девы Марии во храм было содержанием праздника Рождества Богородицы, о чем говорит 2-й канон Рождества Богородицы, составленный препо" },
  { key: "12-07", name: "Вмц. Екатерины", kind: "saint", desc: "В царствование нечестивого императора римского Максимина II [1] в городе Александрия [2] жила девица, по имени Екатерина, происходившая из царского рода [3] .", lifeId: "ekaterina" },
  { key: "12-07", name: "вмч. Меркурия", kind: "saint", desc: "Святой великомученик Меркурий, скиф по происхождению, служил воином в римской армии. Нечестивые императоры Декий (249-251) и Валериан (253-259) издали закон, повелевавший всем римским гражданам поклоняться языческим богам и осуждавший на смерть христиан." },
  { key: "12-07", name: "мч. Меркурия Смоленского", kind: "saint", desc: "Воин, потомок княжеского рода. Воспитанный в православии святой воин тайно вел подвижническую жизнь: был строгим постником, девственником, каждую ночь он втайне от всех воспевал благодарственные хваления Господу." },
  { key: "12-07", name: "Прп. Меркурия, постника Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Меркурий Печерский, постник, подвизался в Киево-Печерском монастыре в XIV веке. Он известен своим духовным союзом с прп. Паисием – святые были неразлучны, жили в одной келье и после смерти были погребены в общем гробу." },
  { key: "12-07", name: "прп. Мастридии Александрийской", kind: "saint", desc: "Преподобная Мастридия жила в Александрии Египетской. Она дала обет девства и, соблюдая пост и безмолвие, пребывала в постоянной молитве. Чистота жизни святой девы была подвергнута испытанию." },
  { key: "12-07", name: "прп. Симона Сойгинского, игумена", kind: "saint", desc: "Родился в Сольвычегодске. Оставив дом родителей, святой принял постриг в монастыре преподобного Корнилия Комельского (&dagger; 1537 г.; память 19 мая/1 июня), где неисходно подвизался в течение многих лет." },
  { key: "12-07", name: "Сщмч. Евграфа Еварестова, пресвитера", kind: "saint", desc: "Священномученик протоиерей Евграф Еварестов родился в 1857 году в Самарской губернии в семье сельского священника. Закончил Самарскую духовную семинарию, после чего поступил на должность преподавателя русского и церковнославянского языков в Самарское духовное училище." },
  { key: "12-07", name: "Евгения Яковлева", kind: "saint", desc: "Священномученик Евгений Никанорович Яковлев родился в 1856 году. В 30‑х годах служил священником в городе Горьком. Был арестован в ноябре 1937 года вместе с большой группой священнослужителей, в том числе священномучеником священником Васил" },
  { key: "12-07", name: "Михаила Богородицкого", kind: "saint", desc: "Богородицкий Михаил Трофимович родился в 1872 году в селе Студенецкие Выселки Липецкого уезда Тамбовской губернии. 33 года отец Михаил прослужил в церкви иконы Божией Матери «Всех скорбящих Радосте» города Козлова Тамбовской области." },
  { key: "12-07", name: "Митрофана Корницкого", kind: "saint", desc: "Митрофан Феодосьевич Корницкий родился в местечке Троянов Житомирской губернии в 1873 году. Начало его священнического служения связано с местечком Осники Черниговской губернии, затем иерей служит в селе Янковцы, потом в селе Клишки." },
  { key: "12-08", name: "Отдание праздника Введения во Храм Пресвятой Богородицы", kind: "feast", desc: "Праздник Введения во храм Богородицы — самый поздний среди двунадесятых. До VIII века воспоминание введения Девы Марии во храм было содержанием праздника Рождества Богородицы, о чем говорит 2-й канон Рождества Богородицы, составленный препо" },
  { key: "12-08", name: "Климента, папы Римского", kind: "saint", desc: "Священномученик Климент – апостол от 70-ти, четвертый епископ (папа) Рима родился в очень знатной семье, состоявшей в родстве с императорской фамилией." },
  { key: "12-08", name: "Петра I, архиепископа Александрийского", kind: "saint", desc: "Святой священномученик Петр, архиепископ Александрийский, родился и вырос в Александрии. Был высокообразован, занимал должность начальника Александрийской школы." },
  { key: "12-08", name: "Прп. Петра Галатийского, Молчальника", kind: "saint", desc: "Современник и друг преподобного Петра блаженный Феодорит , епископ Кирский, сообщает об этом великом подвижнике следующие высоко назидательные сведения." },
  { key: "12-08", name: "Прмц. Магдалины (Забелиной), инокини", kind: "saint", desc: "Преподобномученица Магдалина родилась в 1863 году в городе Орле в семье рабочего Сергея Забелина и в крещении была наречена Марией. В 1876 году, когда ей исполнилось тринадцать лет, она поселилась в селе Посошки Кромского уезда Орловской губернии." },
  { key: "12-08", name: "Серафима (Остроумова), архиепископа Смоленского", kind: "saint", desc: "Священномученик архиепископ Серафим (в миру Михаил Митрофанович Остроумов) родился в 1880 году в Москве в семье псаломщика. Он закончил Московскую Духовную Академию и остался в ней профессорским стипендиатом." },
  { key: "12-08", name: "Григория Воинова", kind: "saint", desc: "Священномученик Григорий родился 26 января 1875 года в селе Теплый Стан Московской губернии в семье псаломщика Александра Воинова. По окончании в 1898 году Вифанской Духовной семинарии он поступил учителем в церковноприходскую школу при храме Казанской иконы Божией Матери у Калужских ворот." },
  { key: "12-08", name: "Иоанна Владимирского", kind: "saint", desc: "Священномученик Иоанн родился 21 марта 1877 года в селе Боронкино Старицкого уезда Тверской губернии в семье священника Михаила Владимирского. Образование получил в Духовной семинарии, в 1906 году он был рукоположен в сан священника ко храму родного села Боронкина, где служил его отец." },
  { key: "12-08", name: "Василия Парийского", kind: "saint", desc: "Священномученик Василий родился 28 июля 1894 года, в день, когда Церковь празднует память равноапостольного великого князя Владимира, во святом крещении Василия, в одном из сел Александровского уезда Владимирской губернии в семье псаломщика Василия Парийского." },
  { key: "12-08", name: "Космы Коротких", kind: "saint", desc: "Священномученик Косма родился 25 октября 1886 года в день памяти преподобного Космы епископа Маиумского в селе Большая Уса Осинского уезда Пермской губернии в семье крестьянина Родиона Коротких." },
  { key: "12-08", name: "Иоанна Тарасова", kind: "saint", desc: "Священномученик Иоанн родился 18 февраля 1867 года в селе Бородино Клинского уезда Московской губернии в семье крестьянина Якова Ивановича Тарасова. Иван окончил городскую начальную школу и с десятилетнего возраста служил у состоятельных торговцев в Клину, а затем перешел служить в контору прокурора Шмидта." },
  { key: "12-08", name: "Симеона Афонькина", kind: "saint", desc: "Семен Иванович Афонькин родился 13 февраля 1870 года в селе Оброчено Краснослободского уезда Пензенской губернии. Отец Симеон был священником в городе Каскелен в Казахстане и с честью нес подвиг пастырского служения в те нелегкие годы." },
  { key: "12-08", name: "Илариона Соловьева", kind: "saint", desc: "Иларион Максимович Соловьев родился в деревне Кавелино Димитриевского уезда Орловской губернии в 1868 году. Из жизни этого священника, пострадавшего за Христа, нам известен только период его заключений и ссылок, то есть непосредственно его мученичество." },
  { key: "12-08", name: "Ярослава Савицкого", kind: "saint", desc: "Священномученик Ярослав родился 28 марта 1882 года в селе Пухлое Бельского уезда Гродненской губернии в семье диакона Исаака Савицкого. Как это часто бывало в семьях духовенства, Ярослав Савицкий решил пойти по стопам отца." },
  { key: "12-09", name: "Прп. Алипия Столпника", kind: "saint", desc: "Преподобный Алипий Столпник родился в 522 году в г. Адрианополе в Пафлагонии. Мать его, благочестивая христианка, рано овдовела и, зная о Божественном призвании сына, поручила его воспитание Феодору, епископу Адрианопольскому." },
  { key: "12-09", name: "Освящение церкви вмч. Георгия в Киеве", kind: "saint", desc: "Вмч. Георгий Победоносец, римский военачальник III-IV веков, родился в Палестине. При императоре Диоклетиане он открыто исповедал свою веру во Христа, раздал имущество бедным и обличил жестокость гонителей.", lifeId: "georgiy" },
  { key: "12-09", name: "свт. Иннокентия (Кульчицкого), епископа Иркутского", kind: "saint", desc: "Прославленный во святых, дивный в чудесах, чтимый ближними и дальними, чудотворец Иннокентий, первый епископ Иркутский, родился в конце XVII века в Малороссии, в Черниговской губернии." },
  { key: "12-09", name: "Прп. Иакова отшельника, Сирийского", kind: "saint", desc: "Преподобный Иаков отшельник подвизался на горе недалеко от города Кира в Сирии. Он страдал тяжелой болезнью, но всегда носил вериги, пищу вкушал лишь вечером и непрестанно молился." },
  { key: "12-09", name: "прп. Стилиана Пафлагонского", kind: "saint", desc: "Родился в городе Адрианополе в Пафлагонии, в Малой Азии, в V веке. Он был благословен от чрева матери своей, и чем старше становился, тем в большей мере по милости Божией Дух Святой поселялся в нем." },
  { key: "12-09", name: "Николая Замараева", kind: "saint", desc: "Николай Васильевич Замараев родился в Великом Устюге 25 мая 1869 года в семье священника. Имея перед собою пример отца, Николай заканчивает Вологодскую Духовную семинарию и после ее окончания в 1890 году становится священником." },
  { key: "12-09", name: "Иоанна Виноградова", kind: "saint", desc: "Священномученик Иоанн родился 5 января 1879 года в селе Преображенском Серпуховского уезда Московской губернии в семье псаломщика Павла Виноградова. В 1901 году Иван Павлович окончил Московскую Духовную семинарию и был назначен законоучител" },
  { key: "12-09", name: "Василия Агафоникова", kind: "saint", desc: "Священномученик Василий родился 5 марта 1885 года в селе Медяны Вятского уезда Вятской губернии в семье Владимира Яковлевича и Марии Андреевны Агафониковых." },
  { key: "12-09", name: "Василия Колосова", kind: "saint", desc: "Василий Иванович Колосов родился 20 января 1876 года в селе Кривандино Коробовского района Московской области в семье псаломщика. Он учился в Рязанской Духовной семинарии, но был вынужден прервать обучение в третьем классе." },
  { key: "12-09", name: "Илии Зачатейского", kind: "saint", desc: "Священномученик Илия родился 12 июля 1884 года в селе Чаплыгино Бронницкого уезда Московской губернии в семье священника Александра Николаевича Зачатейского, служившего в Богородице-Рождественском храме того же села." },
  { key: "12-09", name: "Василия Студницына", kind: "saint", desc: "Священномученик Василий родился 18 марта 1890 года в городе Серпухове Московской губернии в семье псаломщика Алексея Студницына. В 1914 году Василий Алексеевич окончил Московскую Духовную семинарию и поступил псаломщиком в кладбищенскую церковь Всех Святых в Серпухове." },
  { key: "12-09", name: "Даниила Мещанинова", kind: "saint", desc: "Священномученик Даниил родился в 1870 году в селе Новинки Серпуховского уезда Московской губернии в семье крестьянина-бедняка Феодота Мещанинова. Из-за бедности семьи Даниил получил только первоначальное образование и в раннем возрасте устроился рабочим." },
  { key: "12-09", name: "Михаила Зеленцовского", kind: "saint", desc: "Михаил Викторович Зеленцовский родился в деревне Яковлево-Массальское Угличского уезда Ярославской губернии в 1878 году в семье титулярного советника. Образование он получил в Покрово-Паисевской церковно-приходской школе, которую окончил в 1900 году." },
  { key: "12-09", name: "прмч. Тихона (Бузова), архимандрита", kind: "saint", desc: "Преподобномученик Тихон родился 16 сентября 1873 года в селе Шонгуты Тетюшского уезда Казанской губернии в семье крестьянина Петра Бузова. При крещении мальчик был наречен Иосифом." },
  { key: "12-10", name: "Иконы Божией Матери, именуемой «Знамение»", kind: "icon", desc: "Икона Божией Матери, именуемая &quot;Знамение&quot;. Знамение Пресвятой Богородицы, бывшее в Новгороде Великом в 1170 году. Икона Божией Матери, именуемая &quot;Знамение&quot; , изображает Пресвятую Богородицу, сидящую и молитвенно подъемлю" },
  { key: "12-10", name: "Знамение Пресвятой Богородицы, бывшее в Новгороде Великом в 1170 году", kind: "feast", desc: "Знамение от иконы Пресв. Богородицы в Новгороде было в 1170 году. Суздальский князь Андрей Боголюбский, замыслив образовать на севере Руси северную державу, соединился с князьями Смоленским, Рязанским, Муромским, Полоцким, Переяславским и Ростовским и хотел одним ударом сразить силу Новгородцев." },
  { key: "12-10", name: "Вмч. Иакова Персянина", kind: "saint", desc: "Святой великомученик Иаков Персянин (Рассеченный) родился в IV веке в благочестивой христианской семье, богатой и знатной. Жена его также была христианкой." },
  { key: "12-10", name: "прп. Палладия Александрийского", kind: "saint", desc: "Монашествовав Богоугодно, Богоносне отче наш,/ молитвою и постом Бога взыскал еси/ и был еси приятелище чисто Духа,/ блистая верным добродетельныя зари,/ имиже просвещаеши вся чтущия тя./ Слава прославльшему тя Христу,/ слава Укрепльшему тя,// слава Действующему тобою всем исцеление." },
  { key: "12-10", name: "свт. Иакова, епископа Ростовского", kind: "saint", desc: "Святитель Иаков, епископ Ростовский, по местному преданию, принял постриг в Копырском на реке Ухтоме монастыре, в 80 километрах от Ростова. Долгое время он был игуменом этого монастыря, а в 1385 году поставлен епископом Ростовским при митрополите Пимене и великом князе Димитрии Донском." },
  { key: "12-10", name: "Обретение мощей блгв. кн. Всеволода, во Святом Крещении Гавриила, Новгородского, Псковского чудотворца", kind: "saint", desc: "Святой благоверный князь Всеволод, в Крещении Гавриил, Псковский, внук Владимира Мономаха, родился и почти всю жизнь прожил в Новгороде, где в 1088–1093 и 1095–1117 годах княжил его отец, святой благоверный князь Мстислав-Феодор Великий (&dagger; 15 апреля 1132)." },
  { key: "12-10", name: "блж. Андрея Симбирского", kind: "saint", desc: "Родился в мещанской семье, с 7 лет избрал подвиг юродства: питался лишь хлебом и ягодами, общался жестами. Ночью молился у стен Вознесенского собора, целуя его ограду." },
  { key: "12-10", name: "Собор новомучеников и исповедников Радонежских", kind: "feast", desc: "В годы безбожных гонений XX века к сонму уже широко известных святых заступников Радонежской земли присоединились многие новомученики и исповедники. Празднование в их честь было внесено в месяцеслов по благословению патриарха Московского и всея Руси Кирилла 2 марта 2011 года." },
  { key: "12-10", name: "Прмчч. монахов 17-ти в Индии", year: "IV", kind: "saint", desc: "Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку 'Сообщить об ошибке' или Ctrl+Enter." },
  { key: "12-10", name: "Прп. Романа Антиохийского (Сирийского)", kind: "saint", desc: "Блаженный Роман родился в городе Росе [1] , близ Антиохии; достигши зрелого возраста, он поселился в Антиохии. Здесь он затворился вне города в малой келлии, где пробыл до старости, не имея при этом огня." },
  { key: "12-10", name: "Николая (Добронравова), архиепископа Владимирского", kind: "saint", desc: "Священномученик Николай (в миру Николай Павлович Добронравов) родился 21 ноября 1861 года в селе Игнатовка Дмитровского уезда Московской губернии в семье священника Павла Добронравова, с 1867 года настоятеля Никольского храма села Ромашково , где Николай провел детство и юность." },
  { key: "12-10", name: "Василия Соколова", kind: "saint", desc: "Священномученик Василий родился в 1872 году в селе Любаново Верейского уезда Московской губернии в семье псаломщика Михаила Соколова. В 1895 году Василий Михайлович окончил Вифанскую Духовную семинарию." },
  { key: "12-10", name: "Бориса Ивановского", kind: "saint", desc: "Священномученик Борис родился в 1897 году в городе Москве в семье почтового служащего Павла Ивановского. Окончил реальное училище и Духовную семинарию – в то время, когда в России совершился государственный переворот и к власти пришли безбожники." },
  { key: "12-10", name: "Феодора Дорофеева", kind: "saint", desc: "Священномученик Феодор родился 7 июня 1885 года в деревне Козлаково Андреевской волости Александровского уезда Владимирской губернии в семье крестьянина Евфимия Дорофеева." },
  { key: "12-11", name: "Прмч. и исп. Стефана Нового", kind: "saint", desc: "Святой преподобномученик и исповедник Стефан Новый родился в 715 году в Константинополе в благочестивой христианской семье. Родители его, имея двух дочерей, молили Господа о рождении сына." },
  { key: "12-11", name: "мч. Иринарха Севастийского и святых семи жен", kind: "saint", desc: "Святой Иринарх происходил из города Севастии [1] . В юном возрасте он был палачом при мучениях святых мучеников. Во время истязания правителем Максимианом, при Диоклитиане, святых семи жен Иринарх был просвещен благодатью Божиею: видя жен, " },
  { key: "12-11", name: "Свт. Феодора, архиепископа Ростовского", kind: "saint", desc: "В миру Иоанн, племянник и ученик преподобного Сергия Радонежского. В 12-летнем возрасте был отдан на воспитание Радонежскому игумену и тогда же пострижен им в иночество с именем Феодор." },
  { key: "12-11", name: "Сщмч. Серафима (Чичагова), митрополита", kind: "saint", desc: "Митрополит Серафим (в миру Леонид Михайлович Чичагов) родился 9 июня 1856 года; он правнук знаменитого адмирала В.Я. Чичагова, одного из первых исследователей Ледовитого океана, и внук П.В." },
  { key: "12-11", name: "Алексия Веселовского", kind: "saint", desc: "Священномученик Алексий родился 15 февраля в 1873 года в селе Губино Можайского уезда Московской губернии в семье псаломщика Александра Веселовского. В 1887 году окончил Перервинское Духовное училище, в 1894 – Вифанскую Духовную семинарию и работал учителем народной школы." },
  { key: "12-11", name: "Алексия Смирнова", kind: "saint", desc: "Священномученик Алексий родился 8 февраля 1890 года в селе Редино Солнечногорской волости Клинского уезда Московской губернии в семье псаломщика Александра Смирнова." },
  { key: "12-11", name: "Василия Завгороднего", kind: "saint", desc: "Василий Назарович Завгородний родился в 1893 году в селе Хижки Конотопского уезда Черниговской губернии. Служил священником в Новокладбищенской церкви в Горьком." },
  { key: "12-11", name: "Рафаила (Тюпина), иеромонаха", kind: "saint", desc: "Преподобномученик Рафаил родился 20 июля 1886 года в селе Юрты Жерновской волости Ливенского уезда Орловской губернии в семье крестьянина Георгия Тюпина и в крещении был наречен Борисом." },
  { key: "12-11", name: "Викентия (Никольского), монаха", kind: "saint", desc: "Преподобномученик Викентий родился в 1888 году в городе Санкт-Петербурге и в крещении был наречен Виктором. Его дед был священником в бедном сельском приходе, но отец его, Александр Петрович Никольский, окончив Духовную семинарию, вышел из " },
  { key: "12-11", name: "мц. Анисии Маслановой", kind: "saint", desc: "Анисия Ивановна Масланова родилась в селе Бармино Макарьевского уезда Нижегородской губернии. Была старостой Предтеченской церкви в Нижнем Новгороде. Осенью 1937 года арестована и обвинена в участии в контрреволюционной церковной повстанческой организации." },
  { key: "12-11", name: "мц. Параскевы Федоровой", kind: "saint", desc: "Определением Священного Синода Русской Православной Церкви от 26 декабря 2006 года в лике новомучеников и исповедников Российских ХХ века были прославлены десять подвижников, материалы о которых были представлены Архангельской, Московской, Рязанской и Саратовской епархиями." },
  { key: "12-11", name: "сщмч. Николая Крылова, пресвитера", kind: "saint", desc: "Священномученик Николай родился 26 апреля 1875 года в селе Петровском Верейского уезда Московской губернии в семье псаломщика Василия Федоровича Крылова." },
  { key: "12-11", name: "прп. Сергия (Сребрянского), исп. архимандрита", kind: "saint", desc: "Исповедник Сергий родился 1 августа 1870 года в селе Трехсвятском Воронежского уезда Воронежской губернии в семье священника Василия Сребрянского и в крещении был наречен Митрофаном." },
  { key: "12-12", name: "Мч. Парамона Вифинского и с ним 370-ти мучеников", kind: "saint", desc: "Святой мученик Парамон и с ним 370 мучеников пострадали за веру во Христа в 250 году при императоре Декии (249–251). Правитель восточных областей Аквиан заточил в темницу 370 христиан, принуждая их отречься от Христа и принести жертву идолам." },
  { key: "12-12", name: "мч. Филумена Анкирского", kind: "saint", desc: "Святой мученик Филумен жил в царствование царя Аврелиана [1] , в Ликаонии [2] , занимаясь продажей жита в Галатии, в городе Анкире [3] . Святой Филумен был оклеветан пред правителем области Феликсом, пред которым он и исповедал себя христиа" },
  { key: "12-12", name: "прп. Акакия Синайского, о котором повествуется в Лествице", kind: "saint", desc: "Прп. Акакий, ученик сурового старца, девять лет терпел жестокие обиды и побои, но всегда отвечал: \"Как перед Господом – мне хорошо\". Даже после смерти, когда старец усомнился в его кончине, Акакий откликнулся из гроба: \"Творящий послушание не может умереть\"." },
  { key: "12-12", name: "Прп. Нектария Печерского, в Ближних пещерах", kind: "saint", desc: "Преподобный Нектарий подвизался в Киево-Печерском монастыре в XII веке. За беспрекословное послушание старшей братии и усердие в трудах св. Нектарий именовался Послушливым." },
  { key: "12-12", name: "сщмч. Сатурнина, первого епископа Тулузского", kind: "saint", desc: "Священномученик Сатурнин [*] (III в.), первый епископ Тулузский, был греком по происхождению и дворянином по рождению. Святой Сатурнин один из семи святых миссионеров, посланных Римом для просвещения Галлии во времена правления Декия (249–251)." },
  { key: "12-12", name: "сщмч. Авива, епископа Некресского (VI)", kind: "saint", desc: "Священномученик Авив, епископ Некресский, – один из тринадцати святых сирийских (каппадокийских) отцов, основателей грузинского монашества, пришедших в Грузию в VI веке." },
  { key: "12-12", name: "свт. Мардария (Ускоковича), епископа Американского и Канадского (1935)", kind: "saint", desc: "Святитель Мардарий (Ускокович) (1889 – 1935) стал первым сербским архиереем на американском континенте с титулом епископ Американский и Канадский. С его именем связано дело административного устроения первой сербской епархии в США и Канаде." },
  { key: "12-12", name: "Сщмч. Сергия Кочурова, пресвитера", kind: "saint", desc: "Священник Сергий родился 17 мая 1892 г. в деревне Деревягино Сапожсковского уезда Рязанской губернии в семье священника Иоанна Кочурова. В 1913 г. окончил Рязанскую духовную семинарию, в 1915 г." },
  { key: "12-13", name: "Ап. Андрея Первозванного", kind: "saint", desc: "Ап. Андрей Первозванный († 62), брат ап. Петра, был рыбаком из Галилеи. Первым последовал за Христом, приведя к Нему и св. Петра. После Пятидесятницы проповедовал в Малой Азии, Фракии, Македонии, прошел Крым, Причерноморье, дошел до поселений славян, где был основан Новгород.", lifeId: "andrey" },
  { key: "12-13", name: "Свт. Фрументия, архиепископа Индийского (Эфиопского)", kind: "saint", desc: "В конце царствования Константина Великого один любознательный тирский купец – христианин, по имени Меропий, отправился путешествовать в Индию [1] , и другие страны по берегам Чермного моря." },
  { key: "12-13", name: "Сщмч. Иоанна Честнова, пресвитера", kind: "saint", desc: "Священномученик Иоанн родился 30 января 1874 года в деревне Запонорье Богородского уезда Московской губернии в семье священника Петра Честнова. В 1904 году по окончании четвертого курса Московской Духовной семинарии Иван Честнов подал прошение об увольнении." },
  { key: "12-14", name: "Прор. Наума", kind: "saint", desc: "Святой пророк Наум – один из 12 малых пророков, родом из селения Елкоша (Галилея). Время его жизни относится к VII в до Р. X. Ветхозаветная книга пророка Наума содержит предсказание гибели ассирийского города Ниневии за его беззакония, разрушение Израильского царства и хулу ассирийского царя Сеннахирима на Иегову." },
  { key: "12-14", name: "Прав. Филарета Милостивого", kind: "saint", desc: "Праведный Филарет Милостивый, сын Георгия и Анны, воспитанный в благочестии и страхе Божием, жил в VIII в. в селении Амнии Пафлагонской области (Малая Азия)." },
  { key: "12-14", name: "мч. Анании Персянина", kind: "saint", desc: "Уроженец Арбелы (ныне Эрбиль, Ирак) в Персии, мирянин, он прославился добродетелями и крепостью веры. Претерпев мучения, святой Анания не отрёкся от веры и был казнён." },
  { key: "12-15", name: "Прор. Аввакума", kind: "saint", desc: "Святой пророк Аввакум, один из 12 малых пророков, происходил из колена Симеонова, пророчествовал около 650 года до Р. X. Пророк Аввакум предрек разрушение Иерусалимского храма, вавилонское пленение и возвращение пленных на родину." },
  { key: "12-15", name: "Прп. Афанасия, затворника Печерского, в Ближних пещерах", kind: "saint", desc: "Подвизался в Киево-Печерской обители в XII веке. Проводя богоугодную подвижническую жизнь, после долгой болезни преподобный Афанасий скончался. На третий день после кончины преподобного, когда игумен с братией пришли совершить погребение, то нашли святого сидящим и плачущим." },
  { key: "12-15", name: "прп. Афанасия, затворника Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный Афанасий Затворник, не желая видеть суеты и прелести мира сего, затворил себя в пещере, чтобы в безмолвии угодить Богу, и там непрестанно стоял на молитве." },
  { key: "12-15", name: "мц. Миропии Хиосской", kind: "saint", desc: "Святая мученица Миропия родилась в г. Ефесе в начале III в. Она рано лишилась отца, и мать воспитала ее в христианской вере. Святая Миропия, посещая гроб мученицы Ермионии (память 4 сентября), дочери апостола Филиппа, брала миро от ее мощей и лечила больных." },
  { key: "12-15", name: "прп. Исе (Иессея), епископа Цилканского (VI)", kind: "saint", desc: "Преподобный Исе (Иессей), епископ Цилканский, родился в Антиохии Сирийской в благочестивой христианской семье. Еще отроком он почувствовал влечение к духовной жизни, а по достижении совершеннолетия с благословения родителей отправился в одн" },
  { key: "12-15", name: "св. Стефана Уроша V, царя Сербского", kind: "saint", desc: "Святой Стефан Урош, царь Сербии, сын царя Душана Немани, родился в 1337 году. В 1346 году он был венчан на королевство. Душан просил для сына руку дочери французского короля, но папа Римский настоял на том, чтобы принцесса не изменяла латинскому исповеданию." },
  { key: "12-15", name: "Сщмч. Матфея Александрова, пресвитера", kind: "saint", desc: "Матфей Иванович Александров родился в 1872 году в селе Верхний Рогачик под Мелитополем. Окончил Киевскую Духовную семинарию и священствовал в церкви святителя Николая в родном селе." },
  { key: "12-15", name: "сщмч. Димитрия Благовещенского, пресвитера", kind: "saint", desc: "Священномученик Димитрий родился 22 октября 1879 года в селе Тимонино Богородского уезда Московской губернии в семье диакона Феодора Благовещенского. По окончании духовной школы Дмитрий поступил в Московскую Духовную семинарию, где отучился один год." },
  { key: "12-15", name: "прп. Веры Графовой, исп., послушницы", kind: "saint", desc: "Преподобномученица Антонина родилась в 1886 году в городе Москве в семье мастерового Ивана Степанова и в крещении была наречена Анной. В одиннадцать лет она поступила в Успенский Брусенский монастырь в городе Коломне и приняла здесь монашеский постриг с именем Антонина." },
  { key: "12-15", name: "Алексия (Бельковского), архиепископа Великоустюжского", kind: "saint", desc: "Священномученик Алексий (в миру Петр Филиппович Бельковский) родился в 1842 году в селе Рождествино Каширского уезда Тульской губернии в семье священника Филиппа Евфимовича Бельковского." },
  { key: "12-15", name: "Константина Некрасова", kind: "saint", desc: "Священномученик Константин родился 15 октября 1872 года в городе Можайске Московской губернии в семье псаломщика Никиты Некрасова. В 1887 году Константин окончил духовное училище, а в 1893 году — Вифанскую Духовную семинарию." },
  { key: "12-15", name: "Николая Заболотского", kind: "saint", desc: "Священномученик Николай родился 24 апреля 1876 года в городе Вязьме Смоленской губернии в семье протоиерея Николая Заболотского, служившего в городе в Воскресенской церкви." },
  { key: "12-15", name: "Сергия Кудрявцева", kind: "saint", desc: "Священномученик Сергий Кудрявцев родился 1 июля 1881 года в селе Фряново Богородского уезда Московской губернии (ныне Щелковский район Московской области)." },
  { key: "12-15", name: "Владимира Проферансова", kind: "saint", desc: "Священномученик Владимир родился 29 июня 1874 года в Москве в семье священника Александра Проферансова. В 1898 году Владимир Александрович окончил Московскую Духовную семинарию и стал служить учителем." },
  { key: "12-16", name: "Прор. Софонии", kind: "saint", desc: "Пророк Софония был современником пророка Иеремии и пророчицы Олдамы. Происходил он из знатного рода. Пророк жил в царском дворце, проповедовал покаяние и помогал царю Иосии истреблять идолопоклонство." },
  { key: "12-16", name: "прп. Саввы, игумена Сторожевского, Звенигородского", kind: "saint", desc: "Прп. Савва Сторожевский, ученик прп. Сергия Радонежского, с юности посвятил себя монашеству. Став духовником братии и игуменом, он основал монастырь на Сторожевской горе, где наставлял иноков в молитве и трудах." },
  { key: "12-16", name: "Прп. Феодула Цареградского", kind: "saint", desc: "Был патрицием в правление Феодосия Великого (378–395), известен был мудростью, благочестием и скромностью. Был назначен епархом царя Феодосия, но покинул свой пост, не желая мириться с несправедливостью." },
  { key: "12-16", name: "прп. Иоанна Безмолвника (Молчальника), бывшего епископа Колонийского", kind: "saint", desc: "Преподобный Иоанн Молчальник (затворник) родился около 454 года в городе Никополе Армянском в семье военачальника Енкратия и супруги его Евфимии. Мальчик рано начал изучать Священное Писание и всем сердцем полюбил уединение и молитву." },
  { key: "12-16", name: "сщмч. Феодора, архиепископа Александрийского", kind: "saint", desc: "Священномученик Феодор, епископ Александрийский, родился в Египте, в Александрии. Этот город прославился в Церкви Вселенской многими мучениками и исповедниками: от святого евангелиста Марка, первомученика Александрийского (&dagger; 63, памя" },
  { key: "12-16", name: "прп. Георгия Черникского", kind: "saint", desc: "Родился в 1730 году в благочестивой православной семье в Сэлиште Сибиуском (Săliște Sibiului). С юности загорелся духом монашеского жития. Однако в то время австрийские властители Трансильвании подавляли православие, особенно православное монашество, склоняя верующих к унии.", lifeId: "georgiy" },
  { key: "12-16", name: "Сщмч. Андрея Косовского, пресвитера", kind: "saint", desc: "Священник Андрей Иудович Косовский (1878-1920) двадцать лет был настоятелем Свято-Екатерининской церкви в г. Феодосия. О его жизни известно, что он получил духовное образование, был женат, в семье родились двое сыновей – Владимир и Дмитрий." },
  { key: "12-16", name: "сщмч. Николая Ершова, пресвитера", kind: "saint", desc: "Священномученик Николай Ершов родился в 1888 году в селе Рюминское в крестьянской семье. Учился в сельской школе. В 1912 году был рукоположен в диакона." },
  { key: "12-16", name: "св. Георгия Седова, исп.", kind: "saint", desc: "Исповедник Георгий (Егор Егорович Седов) родился в 1883 году в деревне Чурилово Владимирской губернии в крестьянской семье. Он принадлежал к тому замечательному типу русских людей, ясность и простота души которых делала все их поступки основательными и каждый шаг надежным.", lifeId: "georgiy" },
  { key: "12-17", name: "прп. Иоанна Дамаскина", kind: "saint", desc: "Преподобный Иоанн Дамаскин родился около 680 года в столице Сирии Дамаске, в христианской семье. Его отец, Сергий Мансур, был казначеем при дворе халифа." },
  { key: "12-17", name: "Прп. Иоанна, епископа Поливотского", kind: "saint", desc: "С юных лет отличался подвижничеством, целомудрием и милосердием; потому и удостоился он поставления во епископа Поливотского. Когда, таким образом, ему поручено было высшее управление и попечение о людях, он усилил и свои подвиги, к прежним трудам присоединяя новые труды." },
  { key: "12-17", name: "свт. Геннадия, архиепископа Новгородского", kind: "saint", desc: "Родился в первой половине XV в. в благочестивой семье Гонзовых. Иноческую жизнь начал в Валаамской обители под руководством св. преподобного Савватия Соловецкого (&dagger; 1435; память 27 сентября по старому стилю)." },
  { key: "12-17", name: "Алексия Сабурова", kind: "saint", desc: "Священномученик Алексий Сабуров в 1914-1915 годах был священником в действующей армии. Потом до декабря 1918 года протоиерей Алексий служил в храме Воскресения Христова и в тюремной церкви города Перми." },
  { key: "12-17", name: "Иоанна Пьянкова", kind: "saint", desc: "Священномученик Иоанн Петрович Пьянков родился в 1856 году в Пермской губернии в семье псаломщика. В 1875 году, по окончании Пермской Духовной семинарии, поступил в Казанскую Духовную академию." },
  { key: "12-17", name: "Александра Посохина", kind: "saint", desc: "Священномученик Алексий Сабуров в 1914-1915 годах был священником в действующей армии. Потом до декабря 1918 года протоиерей Алексий служил в храме Воскресения Христова и в тюремной церкви города Перми." },
  { key: "12-17", name: "Николая Яхонтова", kind: "saint", desc: "Священномученик Иоанн Петрович Пьянков родился в 1856 году в Пермской губернии в семье псаломщика. В 1875 году, по окончании Пермской Духовной семинарии, поступил в Казанскую Духовную академию." },
  { key: "12-17", name: "Василия Кашина, диакона, и с ним 10-ти мучеников", kind: "saint", desc: "Василий Кашин служил диаконом в Троицкой церкви села Сылвинское-Троицкое Пермского уезда Пермской губернии. Расстрелян 17 декабря 1918 года вместе с 10 прихожанами в ходе массовых репрессий в Пермском крае." },
  { key: "12-17", name: "сщмч. Димитрия Неведомского, пресвитера", kind: "saint", desc: "Священномученик Димитрий родился 4 сентября 1882 года в Твери, в семье чиновника Земской уездной управы. В 1902 году Дмитрий Михайлович окончил Тверскую духовную семинарию и стал работать преподавателем в школе и псаломщиком." },
  { key: "12-17", name: "прмц. Анастасии Титовой, послушницы", kind: "saint", desc: "Преподобномученица Анастасия родилась 8 октября 1873 года в селе Машутино Александровского уезда Владимирской губернии в семье крестьянина Петра Титова." },
  { key: "12-17", name: "Екатерины Арской", kind: "saint", desc: "Мученица Екатерина Андреевна Арская родилась в 1875 году в Санкт-Петербурге в семье богатого купца Андрея Петровича Уртьева, потомственного почетного гражданина столицы Российской империи." },
  { key: "12-17", name: "Киры Оболенской", kind: "saint", desc: "Кира Ивановна Оболенская родилась в 1889 году в семье князя Ивана Дмитриевича Оболенского. Древний род Оболенских восходит еще к князю Рюрику. В 10-летнем возрасте Кира была отдана в Смольный институт благородных девиц в Санкт-Петербурге, который окончила в 1904 году с серебряной медалью." },
  { key: "12-18", name: "Прп. Саввы Освященного", kind: "saint", desc: "Преподобный Савва Освященный родился в V веке в Каппадокии, в благочестивой христианской семье Иоанна и Софии. Его отец был военачальником. Уехав по делам службы в Александрию, он взял с собой жену, а пятилетнего сына оставил на попечение дяди." },
  { key: "12-18", name: "Свт. Гурия, архиепископа Казанского", kind: "saint", desc: "Свт. Гурий (в миру Григорий Руготин, †1563), первый архиепископ Казанский, происходил из радонежских дворян. В юности, оклеветанный, два года провёл в заточении, после чего принял монашество в Иосифо-Волоколамском монастыре." },
  { key: "12-18", name: "мч. Анастасия Аквилейского", kind: "saint", desc: "Св. мученик Анастасий Аквилейский пострадал в III веке. За проповедь христианства в Далмации он был схвачен, мужественно исповедал веру во Христа и казнён язычниками, которые бросили его тело в море." },
  { key: "12-18", name: "Сщмч. Илии Четверухина, пресвитера", kind: "saint", desc: "Священномученик Илия родился 14 января 1886 года в Москве в семье Николая Михайловича и Марии Николаевны Четверухиных. Николай Михайлович был сыном учителя, выходца из солдатского сословия; по окончании учительской семинарии он более 45 лет" },
  { key: "12-18", name: "прмч. Геннадия (Летюка), иеромонаха", kind: "saint", desc: "Преподобномученик Геннадий (в миру Григорий Лаврентьевич Летюк) родился в 1874 году в селе Беловоды Мариупольского уезда Харьковской губернии, в семье украинского крестьянина." },
  { key: "12-18", name: "св. Сергия Правдолюбова, исп., пресвитера", kind: "saint", desc: "Священноисповедник протоиерей Сергий Правдолюбов родился в 1890 году в селе Маккавеево в Рязанской губернии в семье учителя Касимовского духовного училища (впоследствии протоиерея Успенской церкви г." },
  { key: "12-19", name: "Свт. Николая, архиепископа Мир Ликийских, Чудотворца", kind: "saint", desc: "Благословен Бог, даровавший нам предивное сокровище – ангелоподобного Николая. Заступничеством и милосердием этого великого светоча евангельского сияния, от края до края освятившего вселенную, весь православный мир устремился к Вечной Жизни.", lifeId: "nikolay" },
  { key: "12-20", name: "Свт. Амвросия, епископа Медиоланского", kind: "saint", desc: "Святой Амвросий родился в 340 году в Северной Италии в богатой и знатной римской семье. Получив прекрасное юридическое образование, он скоро возвысился и с 370 года занял должность консульского префекта (правителя) провинций Лигурии и Эмилии.", lifeId: "ambrosiy-medio" },
  { key: "12-20", name: "прп. Нила Столобенского", kind: "saint", desc: "Крестьянин из Новгородской земли, принял постриг в Крыпецком монастыре. После 10 лет в обители удалился в пустынь на реку Серемлю, затем по Божественному указанию поселился на острове Столобный на озере Селигер." },
  { key: "12-20", name: "прп. Антония Сийского, иеромонаха", kind: "saint", desc: "Преподобный Антоний Сийский, в миру Андрей, родился в семье богатого земледельца в селе Кехта близ Северной Двины. В детстве получил хорошее воспитание, много читал и выучился иконописи." },
  { key: "12-20", name: "Прп. Иоанна, постника Печерского, в Ближних пещерах", kind: "saint", desc: "Преподобный Иоанн Печерский, постник, подвизался в Киево-Печерском монастыре в XII веке и погребен в Ближних пещерах. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и" },
  { key: "12-20", name: "прмч. Афинодора Месопотамского", kind: "saint", desc: "Святой мученик Афинодор, из Сирской Месопотамии, с юных лет вел иноческую жизнь. По доносу был схвачен и осужден правителем страны Елевсием на жестокие пытки." },
  { key: "12-20", name: "прп. Павла Послушливого", kind: "saint", desc: "Время жизни преподобного Павла Послушливого (Повинника) неизвестно. Сохранилось лишь краткое житие, в котором говорится, что он был сыном состоятельных родителей." },
  { key: "12-20", name: "мц. Филофеи Румынской (XI)", kind: "saint", desc: "Родилась в Тырново, возможно около 1206 года. Её отцом был болгарин-земледелец, а мать – валашка. Мать взрастила дочь в истинно христианском духе, но вскоре скончалась." },
  { key: "12-20", name: "Сергия (Гальковского), иеромонаха", kind: "saint", desc: "Иван Гальковский родился в Витебской губернии. 11 марта 1908 года он был зачислен в послушники Валаамского Спасо-Преображенского монастыря Выборгской губернии, а 23 декабря 1910 г." },
  { key: "12-20", name: "Андроника (Барсукова), иеродиакона", kind: "saint", desc: "Иеродиакон Андроник (Барсуков) родился в 1872 году в Олонецкой губернии. 27 ноября 1895 года он поступил в Вааламский Спасо-Преображенский монастырь (Выборгская губерния), в послушники которого был официально зачислен 8 августа 1900 г." },
  { key: "12-20", name: "сщмч. Антония Попова, пресвитера", kind: "saint", desc: "Священномученик Антоний Попов родился в 1844 году в Пермской губернии. Служил в Вознесенской церкви в поселке Суксунский Завод. Когда произошла революция, отцу Анатолию было уже 73 года." },
  { key: "12-20", name: "Сергия Голощапова", kind: "saint", desc: "Священномученик Сергий родился 6 июня 1882 года в Московской губернии в деревне Баньки, в которой располагалась в то время Знаменская мануфактура Полякова, где его отец Иван Голощапов долгое время работал художником по тканям." },
  { key: "12-20", name: "Михаила Успенского", kind: "saint", desc: "Священномученик Михаил родился в 1874 году в селе Кишкино Михневской волости Серпуховского уезда Московской губернии в семье псаломщика Алексея Успенского, происходившего из крестьянского сословия." },
  { key: "12-20", name: "Сергия Успенского", kind: "saint", desc: "Сергей Михайлович Успенский родился в городе Можайске Московской губернии в 1878 году. Образование он получил в Московском Донском и московском Заиконоспасском духовных училищах, а в 1898 году окончил Московскую Духовную семинарию, в которой еще четыре года после окончания (до 1902 г.) проработал надзирателем." },
  { key: "12-20", name: "Никифора Литвинова, диакона", kind: "saint", desc: "Никифор Романович Литвинов родился 1 июня 1892 года в селе Серетино Тамарского района Курской области в семье крестьянина. Он окончил сельскую школу в 1913 году, после чего был взят на службу в армию, где служил в полковой церкви псаломщиком до 1917 года." },
  { key: "12-21", name: "Прп. Патапия Фивского", kind: "saint", desc: "В Египте на реке Ниле был город, называвшийся Фивы [1] . В этом городе родился блаженный Патапий. Родители его были христиане и воспитали своего сына в благочестии и страхе Божием." },
  { key: "12-21", name: "Прп. Кирилла Челмогорского", kind: "saint", desc: "Просветитель чуди. Родился в городе Белоозере. Принял постриг в обители преподобного Антония Римлянина (&dagger; 1147 г.; память 3/16 августа), где шесть лет проходил различные послушания, а затем, после трехлетнего странствования по пустыням, поселился в дикой Каргопольской стороне." },
  { key: "12-21", name: "Мчч. 62-х иереев и 300 мирян, в Африке от ариан пострадавших", year: "477", kind: "saint", desc: "При императоре Зеноне (474–491) правитель Вандальского королевства в Северной Африке Гунерих при пособничестве арианских епископов воздвиг жестокое гонение на православных." },
  { key: "12-21", name: "мц. Анфисы в Риме", kind: "saint", desc: "Мученица Анфиса пострадала за Христа в Риме в V веке. Была женой римского сановника, крещена святителем Амвросием Медиоланским . Святая мученица была сожжена, после того как отказалась от предложения жены градоначальника Сунильды принять арианское крещение." },
  { key: "12-21", name: "Сщмч. Сергия Орлова, пресвитера", kind: "saint", desc: "Священномученик Сергий родился в 1888 году в селе Кувякино Подольского района Московской области. Отец его был священником в селе Подушкино (ж. д. ст. Кунцево)." },
  { key: "12-22", name: "Зачатие прав. Анною Пресвятой Богородицы", kind: "feast", desc: "22 декабря Русская Православная Церковь вспоминает день чудесного зачатия Пресвятой Девы Марии праведной Анной. Святая праведная Анна была младшей дочерью священника Матфана, происходившего из колена Левина из рода Ааронова.", lifeId: "ioakim-anna" },
  { key: "12-22", name: "Пророчц. Анны, матери прор. Самуила", kind: "saint", desc: "Святая пророчица Анна состояла в супружестве с Елканой и была бесплодной. Елкана взял себе еще другую жену, Феннану, от которой рождались дети. Анна сильно скорбела о своем несчастии, и, каждый день молясь о разрешении бесплодия, дала обет посвятить дитя Богу." },
  { key: "12-22", name: "свт. Софрония, архиепископа Кипрского", kind: "saint", desc: "Преподобный Софроний был сыном христианских богомудрых родителей, живших на острове Кипре. Он получил хорошее образование, но предпочтительно занимался писаниями святых отцов, день и ночь поучаясь в Законе Божием; вместе с тем и жизнь свою он благоустроял по заповедям Господним." },
  { key: "12-22", name: "прп. Стефана Новосиятеля", kind: "saint", desc: "Преподобный Стефан [1] родился и воспитание получил в Константинополе. Родители его, Захария и Феофания, отличались благочестием и добродетелями христианскими; жили они недалеко от святого храма первомученика архидиакона Стефана." },
  { key: "12-22", name: "Сщмч. Владимира Виноградова, пресвитера", kind: "saint", desc: "Священномученик Владимир Флегонтович Виноградов родился 24 октября 1874 года в семье псаломщика. По окончании в 1900 году Ярославской Духовной семинарии был определен псаломщиком к церкви в селе Староандреевском Романово-Борисоглебского уезда Ярославской губернии." },
  { key: "12-22", name: "Нечаянная Радость", kind: "saint", desc: "На иконе Божией Матери «Нечаянная Радость» изображен человек, молящийся на коленях перед иконой Пресвятой Богородицы. Иконографическим сюжетом для образа послужило предание об исцелении некоего юноши от плотской страсти через святой образ В" },
  { key: "12-23", name: "свт. Иоасафа, епископа Белгородского", kind: "saint", desc: "Свт. Иоасаф (Горленко) родился в 1705 году в Малороссии. Окончил Киевскую духовную академию, принял монашество. Прошел путь от иеродиакона до епископа Белгородского (с 1748 года)." },
  { key: "12-23", name: "Мч. Гемелла Пафлагонянина", kind: "saint", desc: "Святой Гемелл происходил из области Пафлагонской [1] . Услыхав, что император Юлиан Отступник [2] находится в городе галатийском Анкире [3] , он отправился туда и, представ пред царем, безбоязненно обличал его в вероотступничестве и вражде против святой христианской веры." },
  { key: "12-23", name: "прп. Фомы Дефуркина, игумена", kind: "saint", desc: "Преподобный Фома Дефуркин родился в Вифинии. С юных лет полюбил иноческое житие и ушел в один из окрестных монастырей. К тому времени, когда византийский сановник Галоликт основал на реке Сагарисе монастырь, преподобный Фома был уже опытным иноком, и братия избрала его настоятелем новой обители." },
  { key: "12-23", name: "Иакова Шестакова", kind: "saint", desc: "Яков Васильевич Шестаков — священник, краевед, писатель, издатель — родился 28 апреля 1858 года в селе Камасино Пермского уезда Пермской губернии в семье священника." },
  { key: "12-23", name: "Александра Шкляева", kind: "saint", desc: "Протоиерей Александр Шкляев служил настоятелем Воскресенской церкви города Соликамска (по другим сведениям он был священником в храме Рождества Пресвятой Богородицы)." },
  { key: "12-23", name: "Анатолия Правдолюбова", kind: "saint", desc: "Священномученик Анатолий родился 6 апреля 1862 года в селе Давыдово Касимовского уезда Рязанской губернии в многодетной семье священника Авдия Семеновича Правдолюбова и супруги его Екатерины Ивановны (урожд." },
  { key: "12-23", name: "Александра Туберовского", kind: "saint", desc: "Священномученик протоиерей Александр Михайлович Туберовский родился в семье священника в селе Макавеево, Касимовского уезда Рязанской губернии 8 марта 1881 года." },
  { key: "12-23", name: "Евгения Харькова", kind: "saint", desc: "Священномученик Евгений родился 1 декабря 1891 года в селе Бетино Касимовского уезда Рязанской губернии в семье диакона Казанской церкви Иакова Николаевича Харькова его супруги Ольги Афанасьевны." },
  { key: "12-23", name: "Константина Бажанова", kind: "saint", desc: "Протоиерей Константин Бажанов родился 3 июня 1879 года в селе Селищи Касимовского уезда Рязанской губернии в семье псаломщика Василия Алексеевича Бажанова и его жены Татианы Исмайловны." },
  { key: "12-23", name: "Николая Карасёва", kind: "saint", desc: "Священномученик Николай родился 23 апреля 1901 года в селе Гусевский Погост Касимовского уезда Рязанской губернии в семье крестьянина-плотника Никиты Николаевича Карасева и его жены Екатерины Васильевны." },
  { key: "12-23", name: "Петра Гришина", kind: "saint", desc: "Петр Гришин родился в 1870 году, проживал в Бельковском районе Рязанской области. 6 ноября 1937 он в числе 27 человек был арестован и заключен сначала в тюрьму города Касимов, а потом всех обвиняемых по делу отвезли в Рязань для вынесения и исполнения приговора." },
  { key: "12-23", name: "Евсевия Тряхова", kind: "saint", desc: "Евсевий Андреевич Тряхов родился в 1870 году в селе Забелино Касимовского уезда Рязанской губернии. Первый раз он был арестован в 1931 году, осужден по статье 61 УК РСФСР и приговорен к 1 году лишения свободы." },
  { key: "12-23", name: "Михаила Якунькина", kind: "saint", desc: "Мученик Михаил родился 7 ноября 1878 года в д. Петрушево Касимовского уезда Рязанской губернии. Деревня Петрушево своего храма не имела, и жители ее входили в состав Погостинского прихода." },
  { key: "12-23", name: "Дорофея Климашева", kind: "saint", desc: "Мученик Дорофей родился 22 июня 1869 года в деревне Полухтино Касимовского уезда Рязанской губернии. Происходил Дорофей Алексеевич из крестьян середняков-единоличников кустарей, а ремеслом он владел самым необходимым — сапожным." },
  { key: "12-24", name: "Прп. Даниила Столпника", kind: "saint", desc: "Преподобный Даниил Столпник родился в селе Вифара, близ города Самосаты в Месопотамии. Мать его Марфа долго была бесплодной и в молитвах дала обет, если родится ребенок, посвятить его Господу." },
  { key: "12-24", name: "Прп. Никона Сухого, Печерского, в Ближних пещерах", kind: "icon", desc: "Преподобный Никон Сухой, сын богатых и знатных родителей, оставил всё Христа ради и принял иночество в Киево-Печерском монастыре. В 1096 году при нашествии хана Боняка он вместе с другими иноками был взят в плен." },
  { key: "12-24", name: "мч. Миракса Египтянина", kind: "saint", desc: "Святой мученик Миракс родился в христианской семье, жившей в городе Теннесе (Египет) в VII веке. Он был воспитан в благочестии, но поддался бесовскому наваждению, попрал святой крест, явился к правителю Египта Амиру, взял в руку меч и поступил на службу к агарянам." },
  { key: "12-24", name: "прп. Луки Столпника, иеромонаха", kind: "saint", desc: "Преподобный Лука, Новый Столпник был воином при византийском императоре Константине Багрянородном (912–959). Во время войны с Болгарией (917) Промыслом Божиим святой Лука остался невредим." },
  { key: "12-24", name: "Сщмч. Феофана (Ильминского), епископа Соликамского, и с ним двух священномучеников и пяти мучеников", kind: "saint", desc: "О Соликамске можно сказать то же, что о многих городах Северной Руси, — основа их благосостояния заключена в благочестии. По добросовестным и упорным трудам Господь даровал благодать, росло благочестие, росло и благосостояние." },
  { key: "12-24", name: "сщмч. Николая Виноградова, пресвитера", kind: "saint", desc: "Священномученик Николай родился 5 апреля 1876 году в городе Дмитрове Московской губернии в семье потомственного священника Михаила Виноградова. После окончания семинарии Николай Михайлович служил учителем Закона Божия." },
  { key: "12-24", name: "сщмч. Иоанна Богоявленского, пресвитера", kind: "saint", desc: "Священномученик Иоанн родился 12 февраля 1892 года в селе Ветрине Моложского уезда Ярославской губернии в семье священника Дмитрия Богоявленского и жены его Людмилы." },
  { key: "12-25", name: "Свт. Спиридона, епископа Тримифунтского, чудотворца", kind: "saint", desc: "Святитель Спиридон Тримифунтский родился в конце III века на острове Кипр. О его жизни сведений сохранилось мало. Известно, что он был пастухом, имел жену и детей.", lifeId: "spiridon" },
  { key: "12-25", name: "Прп. Ферапонта Монзенского", kind: "saint", desc: "Начал подвижничество в Москве, возможно, как юродивый. Принял постриг в Костромском Воздвиженском монастыре, где прожил 13 лет. Позже явился во сне инокам Пафнутию и Андриану, повелев основать Благовещенский монастырь на реке Монзе." },
  { key: "12-25", name: "сщмч. Александра, епископа Иерусалимского", kind: "saint", desc: "Выдающийся церковный просветитель III века. Ученик Климента Александрийского и друг Оригена. Начав служение епископом во Флавии (Каппадокия), он претерпел гонения при Септимии Севере." },
  { key: "12-25", name: "мч. Разумника (Синезия)", kind: "saint", desc: "Святой мученик Разумник [1] родом был римлянин и в юношеском возрасте был отдан своими родителями епископу Римскому для обучения божественным книгам. И так как с обучением книгам он обнаружил и добрый нрав, то возведен был в должность церковного чтеца." },
  { key: "12-26", name: "мц. Лукии Сиракузской", kind: "saint", desc: "Родом из Сиракузы. В благодарность за исцеление матери при гробе св. мученицы Агафии (память 5/18 февраля) в Катанах она раздала все свое имение бедным и дала Господу обет девства." },
  { key: "12-26", name: "Прп. Аркадия Новоторжского", kind: "saint", desc: "Прп. Аркадий Вяземский и Новоторжский (XI в.) подвизался в юродстве Христа ради. Родом из Вязьмы, он с детства отличался благочестием. Под духовным руководством прп." },
  { key: "12-26", name: "прп. Мардария, затворника Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный Мардарий, затворник Печерский, подвизался в Дальних пещерах в XIII веке. По рукописным святцам, в тропаре и кондаке он называется «нестяжательным», а по надписи у мощей – «бескелейным»." },
  { key: "12-26", name: "преставление прп. Германа Аляскинского", kind: "saint", desc: "Прп. Герман Аляскинский (1757-1837) родился в Серпухове в купеческой семье. В 16 лет начал иноческий путь в Троице-Сергиевой пустыни под Петербургом, затем перешел на Валаам, где 15 лет подвизался в уединении." },
  { key: "12-26", name: "прп. Арсения Латрийского, игумена", kind: "saint", desc: "Преподобный Арсений, сын богатых, знатных и благочестивых родителей, был родом из Константинополя. Император отличил его и сделал военачальником и патрицием Киверриотским." },
  { key: "12-26", name: "свт. Досифея (Барилэ), митрополита Молдавского (1693)", kind: "saint", desc: "Досифей (Барилэ) (Dosoftei (Barilă)) (1624–1701), митрополит Азовский, Молдавский, зачинатель румынского стихосложения и книжности, святитель, почитается как один из величайших православных архиереев Молдавии." },
  { key: "12-26", name: "Сщмч. Александра Юзефовича, пресвитера", kind: "saint", desc: "Отец Александр Юзефович был священником церкви села Кара-Балта Пишпекского уезда Семиреченской области (ныне город близ Бишкека, Киргизия). В период установления в Семиречье советской власти, 17 января 1921 года, он был расстрелян в Семиреченской области." },
  { key: "12-26", name: "мч. Иоанна Менькова", kind: "saint", desc: "Иван Никитич Меньков родился в 1884 году. Он служил псаломщиком в церкви села Кара-Балта, Пишпекского уезда Семиреченской области Туркестанского края, в той самой церкви, в которой служил отец Александр Юзефович." },
  { key: "12-26", name: "Владимира Лозины-Лозинского", kind: "saint", desc: "Священномученик Владимир Константинович Лозина-Лозинский, протоиерей, родился 26 мая 1885 года в городе Духовщина Смоленской губернии, в семье земских врачей." },
  { key: "12-26", name: "Александра Поспелова", kind: "saint", desc: "Священномученик Александр родился 21 марта 1883 года в городе Владимире в семье чиновника государственного казначейства, коллежского асессора Василия Владимировича Поспелова." },
  { key: "12-26", name: "Иакова Гусева", kind: "saint", desc: "Яков Иванович Гусев родился 19 октября 1887 года в селе Дивеево Ардатовского уезда Нижегородской губернии в семье священника Серафимо-Дивеевского монастыря протоиерея Иоанна Феофановича Гусева." },
  { key: "12-26", name: "Алексия Рождественского", kind: "saint", desc: "Алексей Иванович Рождественский родился 22 марта 1865 года в селе Введенское Тарусского уезда Калужской губернии. Он происходил из семьи священника и получил образование в Вифанской духовной семинарии." },
  { key: "12-26", name: "Григория Фаддеева", kind: "saint", desc: "Пресвитер Григорий Фаддеев мученичеством своим просиял на Брянской земле. О жизни его известно очень мало. Он родился в 1895 году и был расстрелян 26 декабря 1937 года." },
  { key: "12-26", name: "сщмч. Николая Амассийского, пресвитера", kind: "saint", desc: "Священномученик Николай родился в 1889 г. в селе Савельевка Николаевского уезда Самарской губернии в семье священника Николая Амасийского (по другим данным — Амассийского)." },
  { key: "12-27", name: "Сщмч. Николая Ковалева, пресвитера", kind: "saint", desc: "Священномученик Николай родился в 1884 году в Новочеркасске в семье канцелярского служащего. В 1919 году в Анапе он был рукоположен в сан иерея. Краткие сведения о его служении известны из уголовного дела, заведенного на отца Николая в Ленинграде в начале 30-х годов." },
  { key: "12-28", name: "прп. Павла Латрийского", kind: "saint", desc: "Преподобный Павел Латрийский был уроженцем города Элен в Пергаме. Рано потеряв отца, он воспитывался в обители святого Стефана во Фригии, а после смерти матери всецело посвятил себя иноческим подвигам в монастыре на горе Латр, близ Милета." },
  { key: "12-28", name: "свт. Стефана исп., архиепископа Сурожского", kind: "saint", desc: "Святитель Стефан исповедник, архиепископ Сурожский, был родом из Каппадокии, обучался в Константинополе. Постригшись в монахи, удалился в пустыню, где провел в подвигах 30 лет." },
  { key: "12-28", name: "Собор Крымских святых", kind: "feast", desc: "Установлен 10 марта 1988 года по инициативе архиепископа Симферопольского и Крымского Леонтия (Гудимова) и по благословению патриарха Московского и всея Руси Пимена." },
  { key: "12-28", name: "сщмч. Илариона (Троицкого), архиепископа Верейского", kind: "saint", desc: "Архиепископ Верейский Иларион (Троицкий, 1886-1929) ‒ выдающийся богослов и церковный деятель, ближайший сподвижник Патриарха Тихона. Окончив Московскую духовную академию, принял монашество (1913) и активно участвовал в восстановлении патриаршества на Поместном Соборе 1917-1918 гг." },
  { key: "12-28", name: "Прп. Трифона Печенгского, Кольского", kind: "saint", desc: "Преподобный Трифон Печенгский, Кольский, в миру Митрофан, родился в Новгородской губернии в семье священника. Благочестивые родители воспитывали сына в страхе Божием." },
  { key: "12-28", name: "мч. Елевферия Византийского", kind: "saint", desc: "Св. мч. Елевферий Кувикуларий (IV в.) – знатный византийский вельможа, принявший христианство. Несмотря на высокое положение, посвятил жизнь молитве и добрым делам." },
  { key: "12-28", name: "прп. Парда отшельника", kind: "saint", desc: "Преподобный Пард отшельник, римлянин, в юности занимался извозным промыслом. Однажды, когда он отправился в Иерихон, под ноги его верблюдам случайно попал отрок." },
  { key: "12-28", name: "Александра Рождественского", kind: "saint", desc: "Священномученик Александр (Александр Александрович Рождественский) родился 11 августа 1874 года в семье священника Благовещенского погоста Новоторжского уезда Тверской губернии; окончил Духовную семинарию и в 1902 году был рукоположен в сан священника ко храму родного села." },
  { key: "12-28", name: "Василия Виноградова", kind: "saint", desc: "1929 год государство объявило началом новых гонений на Православную Церковь. 11 мая 1931 года милиционер села Толмачи Тверской области, где служил священник Василий Виноградов, подал рапорт начальнику ОГПУ: &quot;Довожу до Вашего сведения, что по Вашему поручению мною установлено следующее." },
  { key: "12-28", name: "Викторина Добронравова", kind: "saint", desc: "Протоиерей Викторин Добронравов родился в 1889 году в Кишиневе в семье священника. В 1914 году закончил Петроградский Политехнический институт, и в том же году тайно уехал в Москву, чтобы стать монахом, но получил благословение не на монашество, а на священство." },
  { key: "12-29", name: "Прор. Аггея", kind: "saint", desc: "Святой пророк Аггей – десятый из 12 малых пророков. Он был из колена Левиина и пророчествовал при персидском царе Дарии Гистаспе (за 500 лет до Р.Х.). По возвращении иудеев из вавилонского плена он убеждал народ достроить второй Иерусалимский храм и возвещал, что в этом храме надлежит «Слову Безначальному в последних временах явитися»." },
  { key: "12-29", name: "Прп. Софии Суздальской", kind: "saint", desc: "Прп. София, в миру великая княгиня Соломония, первая жена Василия III, была насильно пострижена в монахини (1525) после 20 лет бездетного брака и сослана под стражу в Суздальский Покровский монастырь, где подвигами изгнала из сердца мирские помыслы, всецело посвятив себя Богу." },
  { key: "12-29", name: "мч. Марина Римского", kind: "saint", desc: "Святой Марин жил в царствование Карина [1] и, будучи благороден по происхождению, несмотря на свой юный возраст, носил звание синклитика или сенатора [2] ." },
  { key: "12-29", name: "блж. царицы Феофании Византийской", kind: "saint", desc: "Блаженная царица Феофания (Феофано), первая супруга императора Льва VI Мудрого (886–911). По наветам была вместе с мужем, тогда еще наследником престола, заключена на три года в темницу." },
  { key: "12-29", name: "Собор Кольских святых", kind: "feast", desc: "Дата празднования Собора Кольских святых перенесена с 28 на 29 декабря по благословению Святейшего Патриарха Кирилла 10 ноября 2021 года. Поименный список Собора утвержден Священным Синодом Русской Православной Церкви 16 мая 2023 года (журн" },
  { key: "12-29", name: "Сщмч. Владимира Алексеева, пресвитера", kind: "saint", desc: "Священномученик Владимир Васильевич Алексеев родился в 1883(?) году. Окончил Пермскую Духовную семинарию, служил в Успенском соборе города Оханска Пермской губернии." },
  { key: "12-29", name: "Аркадия (Остальского), епископа Бежецкого", kind: "saint", desc: "Священномученик Аркадий, епископ Лубенский, викарий Полтавский (в миру Остальский Аркадий Иосифович) родился в апреле 1888 года в селе Яковицы Житомирской губернии в семье священника Иосифа Остальского." },
  { key: "12-29", name: "Илии Чередеева", kind: "saint", desc: "Священномученик Илия родился 20 июля 1878 года в городе Кашине Тверской губернии в семье священника Иоанна Чередеева. В 1901 году он окончил Тверскую Духовную семинарию и был рукоположен в сан священника." },
  { key: "12-29", name: "Павла Фаворитова", kind: "saint", desc: "Священномученик Павел (Фаворитов) родился в 1883 году в селе Осенево Угличского района Ярославской области. Служил священником в селе Константиново Тверской области, проживал в городе Калязине." },
  { key: "12-29", name: "Владимира Дамаскина", kind: "saint", desc: "Священномученик Владимир родился 27 февраля 1870 года в городе Торжке Тверской губернии в семье псаломщика Николая Дамаскина. Последние годы жизни его отец служил в селе Георгиевском Новоторжского уезда; скончался в 1914 году." },
  { key: "12-29", name: "Александра Колоколова", kind: "saint", desc: "Священномученик Александр родился 7 марта 1880 года в селе Никольское-Неверьево Корчевского уезда Тверской губернии в семье священника Николая Колоколова." },
  { key: "12-29", name: "Петра Зиновьева", kind: "saint", desc: "Священномученик Пётр Константинович Зиновьев родился 20 июня 1894 г. в селе Березники Вольского уезда Саратовской губернии (ныне село Березняки в Воскресенском районе Саратовской области) в семье священника местного Свято-Никольского храма Константина Зиновьева." },
  { key: "12-29", name: "прмчч. Макария", kind: "saint", desc: "Преподобномученик Макарий (в миру Михаил Ефимьевич Смирнов) родился 1 апреля 1877 года в селе Мелехово Санкт-Петербургской губернии в семье крестьян Евфимия и Анны." },
  { key: "12-29", name: "Феодосия (Болдырева), иеромонахов", kind: "saint", desc: "Преподобномученик Феодосий (Болдырев) (в миру, Федор Федорович) – родился 8 февраля 1868 года в селе Елань-Колено Новохоперского уезда Воронежской губернии; принял монашество, рукоположен в сан иеромонаха; с 1914 года и до закрытия пустыни " },
  { key: "12-30", name: "Прп. Даниила исп. (в схиме Стефана) Нивертского", kind: "saint", desc: "Преподобный Даниил исповедник, в схиме Стефан, был испанским вельможей, начальником острова Ниверта. Пренебрегая мирской славой, он принял в Риме иночество и отправился к святым местам в Константинополь и Иерусалим, где принял схиму." },
  { key: "12-30", name: "Сергия Флоринского", kind: "saint", desc: "Протоиерей Сергий Флоринский родился в древнем городе Суздале 4 марта 1873 года в семье священника церкви святых бессеребренников Космы и Дамиана Феодора Флоринского." },
  { key: "12-30", name: "Петра Покровского", kind: "saint", desc: "Священномученик Петр родился в 1873 году в селе Кондоль Петровского уезда Саратовской губернии в семье священника Иоанна Покровского. Окончил Саратовскую Духовную семинарию." },
  { key: "12-30", name: "Иоанна Земляного", kind: "saint", desc: "Священномученик Иоанн родился в 1867 году в селе Петриковка (Петрановка) Новомосковского уезда Екатеринославской губернии. С 1915 года Иван Петрович служил псаломщиком в селе Дмитриевка Лозовского района Восточно-Казахстанской области." },
  { key: "12-31", name: "Прп. Севастиана Сохотского, Пошехонского", kind: "saint", desc: "Преподобный Севастиан Сохотский, Пошехонский (&dagger; ок. 1500/1542 [1] ) основал монастырь в честь Преображения Господня на реке Сохоти в 90 верстах от города Романова (ныне Тутаев Ярославской области)." },
  { key: "12-31", name: "прославление прав. Симеона Верхотурского (Меркушинского)", kind: "saint", desc: "Праведный Симеон Верхотурский, дворянин по происхождению, оставил всё и удалился в Сибирь, где вёл жизнь смиренного странника. Он нёс слово Божие местным жителям, в том числе иноверцам-вогулам, и славился своим нестяжательством, смирением и молитвенными подвигами." },
  { key: "12-31", name: "свт. Модеста, патриарха Иерусалимского", kind: "saint", desc: "Святитель Модест, патриарх Иерусалимский, родился в Севастии Каппадокийской (Малая Азия) в христианской семье. С юных лет он почувствовал влечение к строгой иноческой жизни." },
  { key: "12-31", name: "прп. Флора, епископа Амийского", kind: "saint", desc: "Преподобный Флор, епископ Амийский, сын христиан Флора и Евфимии, которые дали ему хорошее образование. Он поступил на придворную службу к византийскому императору и был возведен в сан патриция; женился и имел детей." },
  { key: "12-31", name: "прп. Михаила Сингелла, исп.", kind: "saint", desc: "Преподобный Михаил исповедник родился в Иерусалиме в семье ревностных христиан и с молодых лет посвятил себя иноческой жизни. После смерти отца мать и сестры святого Михаила ушли в монастырь, а преподобный Михаил был посвящен в сан пресвитера." },
  { key: "12-31", name: "прп. Даниила Пустынника, иеросхимонаха", kind: "saint", desc: "Преподобный Даниил (мирское имя Думитру) жил во второй половине XV века. Родился в крестьянской семье в Северной Молдове. Подвизался в монастыре Рэдэуца (Буковина), затем поселился в уединенной местности." },
  { key: "12-31", name: "Мч. Виктора Матвеева", kind: "saint", desc: "Мученик Виктор Матвеевич Матвеев родился 11 октября 1871 года в городе Боровичи Новгородской губернии. В юности был парализован, исцелён прав. Иоанном Кронштадтским, который благословил Виктора Матвеева на странничество." },
  { key: "12-31", name: "Фаддея (Успенского), архиепископа Тверского и Кашинского", kind: "saint", desc: "Сщмч. Фаддей (Успенский, 1872–1937), архиепископ Тверской, был выдающимся церковным деятелем. Получив образование в Московской Духовной Академии, принял монашество." },
  { key: "12-31", name: "Николая (Клементьева), архиепископа Великоустюжского", kind: "saint", desc: "Священномученик Николай, архиепископ Великоустюжский (в миру Николай Федорович Клементьев) родился в 1873 году в Костромской губернии в семье священника." },
  { key: "12-31", name: "Илии Бенеманского", kind: "saint", desc: "Служитель Церкви, воин Христов, пастырь добрый — таким был священник Илья Бенеманский. Господь щедро оделил его талантами. Он был искренним в своем ревностном служении Богу и обладал даром проповеди, которая оживотворяла сердца, пробуждая в душах стремление к жизни вечной." },
  { key: "12-31", name: "Иоанна Миронского", kind: "saint", desc: "Священник Иван Николаевич Миронский (Мироновский) родился в селе Русские Юрткули Спасского уезда Казанской губернии в 1877 году. Первый раз его арестовали в 1929 году, но на тот раз под стражей он пробыл не более 5 дней и был выпущен." },
  { key: "12-31", name: "Владимира Преображенского", kind: "saint", desc: "Священномученик Владимир Григорьевич Преображенский родился в 1873 году в селе Троицкое Смоленской губернии. В 1929 году был арестован, Коллегией ОГПУ приговорен к 3 годам лагерного заключения." },
  { key: "12-31", name: "Николая Кобранова", kind: "saint", desc: "Священномученик Николай родился 10 мая 1893 года в селе Благовещенье Дорогобужского уезда Смоленской губернии в семье диакона Иакова Кобранова. В 1913 году Николай окончил Смоленскую Духовную семинарию и поступил на юридический факультет Варшавского университета, в котором проучился три года." },
  { key: "12-31", name: "сщмч. Сергия Астахова, диакона", kind: "saint", desc: "Диакон Сергий Николаевич Астахов родился в Москве, в семье рабочего, 5 июня 1877 года. Образование он получил в народной школе. Сергей Николаевич был женат на Анне Никифоровне и у них родилось пятеро детей." },
];
